rtk env PATH="$PWD/.venv/bin:$PATH" python -c 'import ast, subprocess, sys
def norm(ref, path):
    tree = ast.parse(subprocess.check_output(["git", "show", f"{ref}:{path}"], text=True), type_comments=True)
    for ti in tree.type_ignores:
        ti.lineno = 0
    for node in ast.walk(tree):
        body = getattr(node, "body", None)
        if isinstance(body, list) and body and isinstance(body[0], ast.Expr) and isinstance(body[0].value, ast.Constant) and isinstance(body[0].value.value, str):
            node.body = body[1:]
    return ast.dump(tree, include_attributes=False)
bad = [p for p in sys.argv[1:] if norm("HEAD^", p) != norm("HEAD", p)]
assert not bad, f"non-prose AST changes: {bad}"' scripts/alert_dedup.py scripts/amend_commit_message.py scripts/backfill_caused_by.py scripts/backtest_bugfix_size.py scripts/build_cloud_adf_corpus.py scripts/build_dc_wiki_corpus.py scripts/canary_bridge.py scripts/capture_jira_fixtures.py scripts/check_cli_json_js_safe.py scripts/check_comment_hygiene.py scripts/check_commit_message_wrap.py scripts/check_complexity_baseline.py scripts/check_config_ownership.py scripts/check_config_reads.py scripts/check_criteria_vocabulary.py scripts/check_deploy_manifest.py scripts/check_destructive_test_exec.py scripts/check_fcntl_import_guard.py
